program.source:
Algoritmo Propina
  Definir cuenta Como Entero;
  Definir amigos Como Entero;
  Leer cuenta;
  Leer amigos;
  Si amigos = 0 Entonces
    Escribir "No hay quien pague";
  Sino
    Escribir "Cada uno paga: ", techo((cuenta + cuenta div 10) / amigos);
  FinSi
FinAlgoritmo

